    public static IReadOnlyList<CapabilityFamily> Search(string query,string? group=null,string? status=null)
    {
        string q=query.Trim();
        bool Matches(CapabilityFamily item)
        {
            if(q.Length==0)return true;
            if(string.Join(' ',item.Name,item.Purpose,item.Prerequisites,item.Consequence).Contains(q,StringComparison.OrdinalIgnoreCase))return true;
            return q.ToLowerInvariant() switch {
                "debloat" or "debloating"=>item.Name is "Provisioned-app removal" or "Deep component stripping" or "Conservative component-store cleanup",
                "apps"=>item.Group=="Apps",
                "wi-fi" or "wifi"=>item.Group=="Drivers"||item.Name=="Hardware preservation planning",
                "unattended"=>item.Name=="Answer-file planning",
                _=>false
            };
        }
        return Items.Where(item=>(group==null||item.Group==group)&&(status==null||item.PrototypeStatus==status)&&Matches(item)).ToArray();
    }
